def rule_based_check(failed_attempts, unknown_device):
    if failed_attempts >= 5 and unknown_device:
        return 'High Risk'
    elif failed_attempts >= 5:
        return 'Medium Risk'
    return 'Low Risk'

print(rule_based_check(8, True))  # Outputs: High Risk
print(rule_based_check(2, False)) # Outputs: Low Risk

