from collections import defaultdict

def detect_password_spraying(auth_events, max_unique_accounts=3):
    # Group distinct accounts targeted by the same password candidate
    password_targets = defaultdict(set)
    for event in auth_events:
        password_targets[event['password_hash']].add(event['username'])

    spraying_detected = []
    for pwd_hash, accounts in password_targets.items():
        if len(accounts) >= max_unique_accounts:
            spraying_detected.append({'hash': pwd_hash, 'account_count': len(accounts)})
    return spraying_detected

events = [
    {'username': 'alice', 'password_hash': 'hashA'}, {'username': 'bob', 'password_hash': 'hashA'},
    {'username': 'charlie', 'password_hash': 'hashA'}, {'username': 'david', 'password_hash': 'hashB'}
]
print('Spraying alerts:', detect_password_spraying(events))
